  drawWires(){if(!this.graph)return;const plane=this.element.querySelector('.material-graph-plane');if(!plane)return;const base=plane.getBoundingClientRect(),svg=plane.querySelector('.node-wires');let width=1500,height=1000;svg.innerHTML=this.edges().map(edge=>{const from=plane.querySelector(`[data-node-id="${edge.from.node}"][data-material-pin="out"][data-pin-id="${edge.from.pin}"]`),to=plane.querySelector(`[data-node-id="${edge.to.node}"][data-material-pin="in"][data-pin-id="${edge.to.pin}"]`);if(!from||!to)return '';const a=from.getBoundingClientRect(),b=to.getBoundingClientRect(),x1=(a.left+a.width/2-base.left)/this.zoom,y1=(a.top+a.height/2-base.top)/this.zoom,x2=(b.left+b.width/2-base.left)/this.zoom,y2=(b.top+b.height/2-base.top)/this.zoom,bend=Math.max(50,Math.abs(x2-x1)*.45);width=Math.max(width,x1+100,x2+100);height=Math.max(height,y1+100,y2+100);return `<path d="M${x1} ${y1} C${x1+bend} ${y1},${x2-bend} ${y2},${x2} ${y2}" fill="none" stroke="#8eb59f" stroke-width="2"/>`;}).join('');svg.setAttribute('width',width);svg.setAttribute('height',height);svg.style.width=width+'px';svg.style.height=height+'px';}
  mutate(change){const next=structuredClone(this.doc.data);if(change(next)===false)return;if(!validMaterialGraph(next.graph)||!validMaterialSurface(next.surface)){this.hooks.error?.('머테리얼 값을 확인하세요.');this.render();return;}this.hooks.before?.();this.doc.data=next;this.hooks.change?.();this.render();}
  click(event){const button=event.target.closest('[data-material-pin]');if(!button)return;event.preventDefault();event.stopPropagation();const direction=button.dataset.materialPin==='out'?'from':'to',node=button.dataset.nodeId,pin=button.dataset.pinId;if(event.altKey){this.mutate(data=>disconnectMaterial(data.graph,node,pin,direction));return;}if(direction==='from'){this.pending={node,pin};this.element.querySelectorAll('.pin.pending').forEach(pin=>pin.classList.remove('pending'));button.classList.add('pending');return;}if(!this.pending)return;const from=this.pending;this.mutate(data=>{const result=connectMaterial(data.graph,from,{node,pin});if(!result.ok){this.hooks.error?.(result.reason);return false;}});this.pending=null;}
