    menu.onclick=e=>{const button=e.target.closest('button');if(!button)return;if(button.dataset.materialAdd)this.add(button.dataset.materialAdd,position);else if(button.hasAttribute('data-material-delete'))this.deleteSelection();menu.remove();};search.oninput=render;search.onkeydown=e=>{if(e.key==='Escape')menu.remove();if(e.key==='Enter')results.querySelector('[data-material-add]')?.click();};render();document.body.append(menu);menu.style.left=Math.max(8,Math.min(event.clientX,innerWidth-menu.offsetWidth-8))+'px';menu.style.top=Math.max(8,Math.min(event.clientY,innerHeight-menu.offsetHeight-8))+'px';search.focus();const close=e=>{if(!menu.contains(e.target)){menu.remove();document.removeEventListener('pointerdown',close,true);}};document.addEventListener('pointerdown',close,true);
