  duplicateSelection(){const clip=copyMaterialNodes(this.graph,this.selected);if(!clip.nodes.length)return;for(const node of clip.nodes){const element=this.element.querySelector(`[data-material-node="${node.id}"]`);if(element)node.px=element.offsetLeft;}const position={x:Math.min(...clip.nodes.map(node=>node.px??node.x))+35,y:Math.min(...clip.nodes.map(node=>node.y))+35};let nodes;this.mutate(data=>{const result=pasteMaterialNodes(data.graph,clip,position);if(!result.ok){this.hooks.error?.(result.reason);return false;}nodes=result.nodes;});if(nodes){this.selected=new Set(nodes.map(node=>node.id));this.render();}}
  fit(selectionOnly=false,zoom){const elements=[...this.element.querySelectorAll('[data-material-node]')].filter(element=>!selectionOnly||!this.selected.size||this.selected.has(element.dataset.materialNode));if(!elements.length)return;const left=Math.min(...elements.map(element=>element.offsetLeft)),top=Math.min(...elements.map(element=>element.offsetTop)),right=Math.max(...elements.map(element=>element.offsetLeft+element.offsetWidth)),bottom=Math.max(...elements.map(element=>element.offsetTop+element.offsetHeight));this.zoom=zoom??Math.max(.25,Math.min(1,(this.element.clientWidth-40)/(right-left),(this.element.clientHeight-40)/(bottom-top)));this.pan={x:(this.element.clientWidth-(right-left)*this.zoom)/2-left*this.zoom,y:(this.element.clientHeight-(bottom-top)*this.zoom)/2-top*this.zoom};this.transform();this.saveView();}
  keydown(event){if(editable(event.target))return;const mod=event.ctrlKey||event.metaKey;if(mod&&['c','x','v','z','y'].includes(event.key.toLowerCase())){event.preventDefault();event.stopPropagation();const key=event.key.toLowerCase();if(key==='c'||key==='x'){this.copySelection();if(key==='x')this.deleteSelection();}else if(key==='v')this.pasteSelection();else{const action=key==='y'||event.shiftKey?this.hooks.redo:this.hooks.undo;if(action){action();this.render();}else this.hooks.error?.('문서의 Undo/Redo 연결을 확인하세요.');}}else if(event.key==='Delete'||event.key==='Backspace'){event.preventDefault();event.stopPropagation();this.deleteSelection();}else if(mod&&event.key.toLowerCase()==='a'){event.preventDefault();event.stopPropagation();this.selected=new Set(this.graph.nodes.map(node=>node.id));this.render();}else if(mod&&event.key.toLowerCase()==='d'){event.preventDefault();event.stopPropagation();this.duplicateSelection();}else if(event.key==='f'||event.key==='F'||event.key==='Home'){event.preventDefault();event.stopPropagation();this.fit(event.key!=='Home');}else if(event.key==='Escape'){this.pending=null;this.selected.clear();this.render();}}
